 "content": "from collections import deque


def transform(grid):
    """Encode each non-background horizontal bar as one cell in a 2x3 grid."""
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    bars = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            while q:
                y, x = q.pop()
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            bars.append(color)
    # The bars are reduced to one colored cell each, packed by color (3 before 2).
    bars.sort(key=lambda color: (color != 3, -color))
    cells = bars[:6] + [0] * max(0, 6 - len(bars))
    return [cells[:3], cells[3:6]]
